import datetime, json, os, pathlib, resource
import pytest

def record(kind, **data):
    path = os.environ.get('QT_RUN_RECORD')
    if path:
        with open(path,'a') as out:
            out.write(json.dumps(dict(kind=kind, at=datetime.datetime.now(datetime.timezone.utc).isoformat(), load=os.getloadavg(), **data))+'\n')

@pytest.hookimpl(trylast=True)
def pytest_sessionstart(session):
    record('start')

def pytest_runtest_logreport(report):
    record('phase', nodeid=report.nodeid, when=report.when, outcome=report.outcome, duration=report.duration)

def pytest_sessionfinish(session, exitstatus):
    record('finish', status=int(exitstatus), maxrss_self=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss, maxrss_child=resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss)


def pytest_addoption(parser):
    parser.addoption('--qt-repeat', type=int, default=1)

def pytest_generate_tests(metafunc):
    count = metafunc.config.getoption('--qt-repeat')
    if count > 1:
        metafunc.fixturenames.append('_qt_repetition')
        metafunc.parametrize('_qt_repetition', range(count))

# End later holds only between completed items, leaving the remaining items for
# another hold if a cold compilation used most of the foreground allocation.
import time
_qt_started = time.monotonic()
_qt_logreport = pytest_runtest_logreport

def pytest_runtest_logreport(report):
    _qt_logreport(report)
    if report.when == 'teardown' and time.monotonic() - _qt_started >= 900:
        record('cooperative_stop', completed=report.nodeid)
        pytest.exit('foreground hold boundary after a completed item', returncode=3)

# Resource watchdog only: preserve every checked-in timeout, and shorten an
# owned compiler/probe command if necessary to end the hold before 20 minutes.
import subprocess
_qt_run = subprocess.run

def _qt_bounded_run(*args, **kwargs):
    command = args[0] if args else kwargs.get('args')
    argv = command if isinstance(command, (list, tuple)) else []
    first = str(argv[0]) if argv else ''
    owned = (first == 'xcrun' and 'swiftc' in argv[:3]) or (first.startswith('/private/tmp/sf-qtlarger/') and pathlib.Path(first).name == 'probe')
    bounded = False
    if owned:
        remaining = 1100 - (time.monotonic() - _qt_started)
        if remaining <= 1:
            record('hold_watchdog_stop', program=pathlib.Path(first).name)
            pytest.exit('foreground hold boundary before owned command', returncode=3)
        original = kwargs.get('timeout')
        if original is None or original > remaining:
            kwargs['timeout'] = remaining
            bounded = True
    try:
        return _qt_run(*args, **kwargs)
    except subprocess.TimeoutExpired:
        if not bounded:
            raise
        record('hold_watchdog_stop', program=pathlib.Path(first).name)
        pytest.exit('foreground hold boundary during owned command', returncode=3)

subprocess.run = _qt_bounded_run
